-- Official AuraFit starter workout library (generated by scripts/starter-library.mjs; edit there).
-- Published by one official, non-login creator profile. Counters start at 0. Idempotent.

INSERT INTO public.profiles (username, handle, role, title, bio)
VALUES ('AuraFit Coach', '@aurafit', 'CREATOR', 'Official AuraFit programming',
        'Starter routines designed by the AuraFit team for every level.')
ON CONFLICT (handle) DO NOTHING;

INSERT INTO public.workout_drops (id, title, tagline, creator_id, vibe_tag, duration_minutes,
    calories_burn_estimate, aura_multiplier, xp_points, difficulty, category, exercises,
    cover_from, cover_to, creator_badge)
SELECT v.id, v.title, v.tagline, p.id, v.vibe_tag, v.duration_minutes, v.calories, v.multiplier, v.xp,
    v.difficulty::public.workout_difficulty_enum, v.category::public.workout_category_enum,
    v.exercises::jsonb, v.cover_from, v.cover_to, 'Official AuraFit'
FROM (VALUES
    ('af_first_quest_fullbody', 'First Quest: Full-Body Starter', 'Your first 12 minutes. No equipment, all the fundamentals.', 'ROOKIE RUN', 12, 90, 1.2, 150, 'NOVICE', 'STRENGTH', '[{"id":"ex_af_fq_1","name":"Bodyweight Squats","targetMuscle":"Quads & Glutes","repsOrSeconds":"3 sets x 12 reps","tips":"Sit back like there is a chair behind you. Knees track over toes, chest stays proud."},{"id":"ex_af_fq_2","name":"Incline Push-Ups (hands on a bench or bed)","targetMuscle":"Chest & Triceps","repsOrSeconds":"3 sets x 8 reps","tips":"Body in one straight line from head to heels. Lower slowly for 2 seconds."},{"id":"ex_af_fq_3","name":"Glute Bridges","targetMuscle":"Glutes & Hamstrings","repsOrSeconds":"3 sets x 15 reps","tips":"Drive through your heels and squeeze at the top for 1 second."},{"id":"ex_af_fq_4","name":"Forearm Plank","targetMuscle":"Core","repsOrSeconds":"3 sets x 20 seconds","tips":"Elbows under shoulders. Brace like someone is about to poke your stomach."}]', '#6366F1', '#8B5CF6'),
    ('af_desk_reset_5', 'Desk Reset: 5-Minute Posture Fix', 'Undo hours of sitting between classes, shifts or gaming sessions.', 'LO-FI GLOW', 5, 25, 1.0, 100, 'NOVICE', 'POSTURE_RESET', '[{"id":"ex_af_dr_1","name":"Chin Tucks","targetMuscle":"Deep Neck Flexors","repsOrSeconds":"10 slow reps","tips":"Glide your head straight back to make a double chin. Hold 2 seconds each rep."},{"id":"ex_af_dr_2","name":"Doorway Chest Stretch","targetMuscle":"Chest & Front Shoulders","repsOrSeconds":"30 seconds per side","tips":"Forearm on the door frame at shoulder height, step through gently. No pain."},{"id":"ex_af_dr_3","name":"Wall Angels","targetMuscle":"Mid Back & Shoulders","repsOrSeconds":"10 slow reps","tips":"Keep your lower back, elbows and wrists touching the wall if you can."},{"id":"ex_af_dr_4","name":"Standing Hip Flexor Stretch","targetMuscle":"Hip Flexors","repsOrSeconds":"30 seconds per side","tips":"Tuck your tailbone under before you lunge forward. Small range, big stretch."}]', '#06B6D4', '#3B82F6'),
    ('af_hiit_ignite_15', 'Ignite: 15-Minute HIIT Circuit', 'Short, sharp intervals that get your heart rate up fast.', 'HIGH VOLTAGE', 15, 170, 1.6, 300, 'HUNTER', 'HIIT', '[{"id":"ex_af_hi_1","name":"Jumping Jacks","targetMuscle":"Full Body","repsOrSeconds":"3 rounds x 40s on / 20s off","tips":"Land softly on the balls of your feet. Step jacks are fine if jumping hurts."},{"id":"ex_af_hi_2","name":"Squat to Reach","targetMuscle":"Legs & Shoulders","repsOrSeconds":"3 rounds x 40s on / 20s off","tips":"Squat down, then drive up and reach both arms overhead."},{"id":"ex_af_hi_3","name":"Mountain Climbers","targetMuscle":"Core & Cardio","repsOrSeconds":"3 rounds x 40s on / 20s off","tips":"Shoulders over wrists. Keep hips level, not piked up."},{"id":"ex_af_hi_4","name":"Skater Hops","targetMuscle":"Legs & Balance","repsOrSeconds":"3 rounds x 40s on / 20s off","tips":"Bound side to side and stick each landing for a beat."},{"id":"ex_af_hi_5","name":"High Knees","targetMuscle":"Cardio","repsOrSeconds":"3 rounds x 30s on / 30s off","tips":"Drive knees to hip height and pump your arms."}]', '#F59E0B', '#EF4444'),
    ('af_push_power_20', 'Push Power: Chest, Shoulders & Triceps', 'A bodyweight push session that scales from beginner to strong.', 'IRON FOCUS', 20, 150, 1.5, 320, 'HUNTER', 'STRENGTH', '[{"id":"ex_af_pp_1","name":"Push-Ups (knees or full)","targetMuscle":"Chest & Triceps","repsOrSeconds":"4 sets x 8-12 reps","tips":"Pick the version where the last 2 reps are hard but clean."},{"id":"ex_af_pp_2","name":"Pike Push-Ups","targetMuscle":"Shoulders","repsOrSeconds":"3 sets x 8 reps","tips":"Hips high, lower the top of your head toward the floor between your hands."},{"id":"ex_af_pp_3","name":"Bench or Chair Dips","targetMuscle":"Triceps","repsOrSeconds":"3 sets x 10 reps","tips":"Keep shoulders down away from your ears. Stop if you feel shoulder pain."},{"id":"ex_af_pp_4","name":"Plank Shoulder Taps","targetMuscle":"Core & Shoulders","repsOrSeconds":"3 sets x 20 taps","tips":"Feet wide for stability. Try not to rock your hips."}]', '#7C3AED', '#DB2777'),
    ('af_leg_day_lite_18', 'Leg Day Lite: No-Equipment Lower Body', 'Build strong legs at home with nothing but your bodyweight.', 'GROUNDED', 18, 140, 1.4, 280, 'HUNTER', 'STRENGTH', '[{"id":"ex_af_ld_1","name":"Reverse Lunges","targetMuscle":"Quads & Glutes","repsOrSeconds":"3 sets x 10 per leg","tips":"Step back long, drop your back knee gently toward the floor."},{"id":"ex_af_ld_2","name":"Split Squat Pulses","targetMuscle":"Quads","repsOrSeconds":"3 sets x 30 seconds per leg","tips":"Stay low and move just a few centimetres up and down."},{"id":"ex_af_ld_3","name":"Single-Leg Glute Bridges","targetMuscle":"Glutes & Hamstrings","repsOrSeconds":"3 sets x 10 per leg","tips":"Keep hips level as you lift."},{"id":"ex_af_ld_4","name":"Wall Sit","targetMuscle":"Quads","repsOrSeconds":"3 sets x 30-45 seconds","tips":"Thighs parallel to the floor, back flat on the wall."},{"id":"ex_af_ld_5","name":"Calf Raises","targetMuscle":"Calves","repsOrSeconds":"3 sets x 20 reps","tips":"Pause at the top. Use a step for a bigger range."}]', '#10B981', '#0EA5E9'),
    ('af_core_armor_10', 'Core Armor: 10-Minute Abs', 'A tight, controlled core session with no crunch spam.', 'STEEL CORE', 10, 70, 1.3, 200, 'NOVICE', 'STRENGTH', '[{"id":"ex_af_ca_1","name":"Dead Bugs","targetMuscle":"Deep Core","repsOrSeconds":"3 sets x 10 per side","tips":"Press your lower back into the floor the whole time. Move slowly."},{"id":"ex_af_ca_2","name":"Side Plank","targetMuscle":"Obliques","repsOrSeconds":"3 sets x 20 seconds per side","tips":"Knees down is a great regression. Hips stay high."},{"id":"ex_af_ca_3","name":"Bird Dogs","targetMuscle":"Core & Lower Back","repsOrSeconds":"3 sets x 8 per side","tips":"Reach long, not high. Keep your hips square to the floor."},{"id":"ex_af_ca_4","name":"Hollow Body Hold","targetMuscle":"Abs","repsOrSeconds":"3 sets x 20 seconds","tips":"Bend your knees to make it easier. Lower back stays glued down."}]', '#8B5CF6', '#06B6D4'),
    ('af_cardio_snack_7', 'Cardio Snack: 7-Minute Energy Boost', 'A quick burst to wake up your body and brain.', 'QUICK HIT', 7, 60, 1.2, 130, 'NOVICE', 'CARDIO_SNACK', '[{"id":"ex_af_cs_1","name":"March or Jog in Place","targetMuscle":"Cardio","repsOrSeconds":"60 seconds","tips":"Start easy and build the pace."},{"id":"ex_af_cs_2","name":"Step Jacks","targetMuscle":"Full Body","repsOrSeconds":"45 seconds","tips":"Low impact: step one foot out at a time."},{"id":"ex_af_cs_3","name":"Fast Feet","targetMuscle":"Legs & Cardio","repsOrSeconds":"30 seconds","tips":"Quick small steps on the balls of your feet."},{"id":"ex_af_cs_4","name":"Shadow Boxing","targetMuscle":"Shoulders & Cardio","repsOrSeconds":"60 seconds","tips":"Light jabs and crosses. Rotate from the hips."},{"id":"ex_af_cs_5","name":"Squat Holds with Arm Circles","targetMuscle":"Legs & Shoulders","repsOrSeconds":"45 seconds","tips":"Hold a half squat while you draw small circles."}]', '#EC4899', '#F59E0B'),
    ('af_mobility_flow_12', 'Recovery Flow: 12-Minute Mobility', 'Loosen tight hips, back and shoulders on rest days.', 'CALM MODE', 12, 40, 1.1, 140, 'NOVICE', 'POSTURE_RESET', '[{"id":"ex_af_mf_1","name":"Cat-Cow","targetMuscle":"Spine","repsOrSeconds":"10 slow reps","tips":"Move one vertebra at a time and breathe with the motion."},{"id":"ex_af_mf_2","name":"World’s Greatest Stretch","targetMuscle":"Hips & Upper Back","repsOrSeconds":"5 per side","tips":"Lunge, hand inside your front foot, then rotate your chest open."},{"id":"ex_af_mf_3","name":"90/90 Hip Switches","targetMuscle":"Hips","repsOrSeconds":"8 per side","tips":"Sit tall. Use your hands for support if you need to."},{"id":"ex_af_mf_4","name":"Thread the Needle","targetMuscle":"Upper Back","repsOrSeconds":"6 per side","tips":"Slide one arm under your body and let your shoulder relax down."},{"id":"ex_af_mf_5","name":"Child’s Pose Breathing","targetMuscle":"Lower Back","repsOrSeconds":"60 seconds","tips":"Long slow breaths into your lower back."}]', '#14B8A6', '#6366F1'),
    ('af_tabata_burn_16', 'Tabata Burn: 4 Rounds of Max Effort', '20 seconds all-out, 10 seconds rest. Four classic Tabatas.', 'REDLINE', 16, 210, 2.0, 380, 'BEAST', 'HIIT', '[{"id":"ex_af_tb_1","name":"Burpees (or Step-Back Burpees)","targetMuscle":"Full Body","repsOrSeconds":"8 rounds x 20s on / 10s off","tips":"Keep form over speed. Step back instead of jumping if needed."},{"id":"ex_af_tb_2","name":"Jump Squats (or Fast Squats)","targetMuscle":"Legs","repsOrSeconds":"8 rounds x 20s on / 10s off","tips":"Land quietly with soft knees."},{"id":"ex_af_tb_3","name":"Push-Up to Plank Jacks","targetMuscle":"Chest & Core","repsOrSeconds":"8 rounds x 20s on / 10s off","tips":"Drop to your knees for the push-up whenever you need to."},{"id":"ex_af_tb_4","name":"Speed Skaters","targetMuscle":"Legs & Cardio","repsOrSeconds":"8 rounds x 20s on / 10s off","tips":"Rest 1 minute between each Tabata block."}]', '#EF4444', '#7C3AED'),
    ('af_monarch_challenge_25', 'Monarch Challenge: 25-Minute Ladder', 'An advanced bodyweight ladder for when you are ready to be tested.', 'FINAL BOSS', 25, 280, 2.5, 450, 'SHADOW', 'STRENGTH', '[{"id":"ex_af_mc_1","name":"Push-Up Ladder","targetMuscle":"Chest & Triceps","repsOrSeconds":"1-2-3-4-5-4-3-2-1 reps, rest 15s between","tips":"Full range on every rep. Switch to knees before your form breaks."},{"id":"ex_af_mc_2","name":"Jumping Lunges (or Alternating Lunges)","targetMuscle":"Legs","repsOrSeconds":"4 sets x 12 total","tips":"Control each landing. Choose the non-jumping version if your knees complain."},{"id":"ex_af_mc_3","name":"Pike Push-Ups","targetMuscle":"Shoulders","repsOrSeconds":"4 sets x 8 reps","tips":"Elevate your feet on a step for a harder variation."},{"id":"ex_af_mc_4","name":"Plank to Down-Dog","targetMuscle":"Core & Shoulders","repsOrSeconds":"4 sets x 10 reps","tips":"Push the floor away as you move into down-dog."},{"id":"ex_af_mc_5","name":"Burpee Finisher","targetMuscle":"Full Body","repsOrSeconds":"1 set x 20 reps","tips":"Steady pace. Rest whenever you need to; just finish all 20."}]', '#111827', '#7C3AED')
) AS v(id, title, tagline, vibe_tag, duration_minutes, calories, multiplier, xp, difficulty, category,
       exercises, cover_from, cover_to)
-- auth_id IS NULL: only the official system profile, never a real user who claims the handle.
JOIN public.profiles p ON p.handle = '@aurafit' AND p.auth_id IS NULL
ON CONFLICT (id) DO NOTHING;
